const tabId = 480038377;
const results = await browserjs(tabId, () => {
  // Find all list items or product cards
  const cards = Array.from(document.querySelectorAll("ol.sku-item-list > li, [data-sku-id]"));
  if (cards.length > 0) {
    return cards.map(c => {
      const title = c.querySelector("h4 a, .sku-title a, a[href*='/site/']")?.textContent?.trim();
      const href = c.querySelector("h4 a, .sku-title a, a[href*='/site/']")?.href;
      const price = c.querySelector("[data-testid='customer-price'], .priceView-hero-price")?.textContent?.trim();
      const btn = c.querySelector("button")?.textContent?.trim();
      return { title, href, price, btn, fullText: c.innerText?.slice(0, 200) };
    });
  }

  // fallback: grab all links containing /site/
  const items = [];
  const headings = document.querySelectorAll("h4");
  for (const h of headings) {
    const a = h.querySelector("a");
    if (a) {
      const parent = h.closest("li") || h.parentElement;
      items.push({
        title: a.textContent.trim(),
        href: a.href,
        text: parent?.innerText?.replace(/\n+/g, " | ")
      });
    }
  }
  return items;
});
