const tabId = 480038377;
const allProductsOnPage = await browserjs(tabId, () => {
  // Let's find all product cards/containers
  const productLinks = Array.from(document.querySelectorAll("a[href*='/product/']"))
    .filter(a => a.href.includes("/sku/") && !a.href.includes("#"));

  // Deduplicate by href
  const seen = new Set();
  const unique = [];
  for (const a of productLinks) {
    if (!seen.has(a.href)) {
      seen.add(a.href);
      // find container
      let parent = a;
      for (let i = 0; i < 6; i++) {
        if (parent.parentElement) parent = parent.parentElement;
      }
      unique.push({
        title: a.innerText.trim(),
        href: a.href,
        text: parent.innerText.replace(/\s+/g, ' ').slice(0, 300)
      });
    }
  }
  return unique;
});
console.log("Found unique products:", allProductsOnPage.length);
for (const p of allProductsOnPage) {
  console.log(`- ${p.title} -> ${p.href}\n  Snippet: ${p.text.slice(0, 150)}`);
}

