const tabId = 480038422;
const fulfillmentDetails = await browserjs(tabId, () => {
  // Let's get the exact text around the price and fulfillment / add to cart area
  const main = document.querySelector("main");
  const priceBlock = document.querySelector(".price-block, .price-section, [data-testid='pricing-summary']") || document.querySelector("h1")?.parentElement;

  // Find all elements containing "Pickup" or "Shipping" or "In Stock" or "Add to Cart"
  const nodes = [];
  const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let n;
  while ((n = walk.nextNode())) {
    const txt = n.textContent.trim();
    if (txt.match(/Pickup|Shipping|stock|availability|Add to Cart|Available/i)) {
      nodes.push(txt);
    }
  }
  return {
    exactPrice: Array.from(document.querySelectorAll("*")).find(el => el.children.length === 0 && el.textContent.trim().startsWith("$59.95"))?.textContent?.trim(),
    fulfillmentTexts: nodes
  };
});
console.log("Fulfillment details:", JSON.stringify(fulfillmentDetails, null, 2));

