args.code:
const tabId = 480038377;
await tool.navigate({ tabId, url: "https://www.barnesandnoble.com/search?q=pokemon+cards" });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });
const items = await browserjs(tabId, () => {
  const anchors = Array.from(document.querySelectorAll("a[href*='/w/']"))
    .filter(a => a.innerText.trim().length > 3);
  const seen = new Set();
  const list = [];
  for (const a of anchors) {
    if (!seen.has(a.href)) {
      seen.add(a.href);
      // find price and availability near this element
      let p = a;
      let price = "";
      for (let i = 0; i < 5; i++) {
        if (p.parentElement) {
          p = p.parentElement;
          const match = p.innerText.match(/\$\d+\.\d{2}/);
          if (match) {
            price = match[0];
            break;
          }
        }
      }
      list.push({ title: a.innerText.trim(), href: a.href, price });
    }
  }
  return list;
});
console.log("Found items on 'pokemon cards':", JSON.stringify(items.slice(0, 15), null, 2));

